const calculateFirstDigit = (day, month) => {
  let firstDigit = 0;
  let temp = 0;
  let currentDay = parseInt(day);
  let currentMonth = parseInt(month);

  while (currentDay !== 0 || currentMonth !== 0) {
    firstDigit += (currentDay % 10) + (currentMonth % 10);
    currentDay = Math.floor(currentDay / 10);
    currentMonth = Math.floor(currentMonth / 10);
  }

  if (firstDigit >= 0 && firstDigit <= 9) {
    return [firstDigit];
  } else {
    while (firstDigit !== 0) {
      temp += firstDigit % 10;
      firstDigit = Math.floor(firstDigit / 10);
    }

    return [temp];
  }
};
const getSum = (num) => {
  let sum = 0;
  while (num !== 0) {
    sum += num % 10; //

    num = Math.floor(num / 10);
  }
  // console.log(sum);
  return sum;
};
const getSingleDigitSum = (num) => {
  while (num > 9) {
    num = getSum(num);
  }
  return num;
};
const calculateFirstDigitRedLine = (day, month, year) => {
  let currentDay = parseInt(day);
  let currentMonth = parseInt(month);
  let currentYear = parseInt(year);
  let sum = getSum(day) + getSum(month) + getSum(year);

  if (sum > 9) {
    const k = sum;
    sum = 0;
    sum = getSingleDigitSum(k);

    return sum;
  } else {
    return sum;
  }
};
const calculateSecondDigit = (day, month, year) => {
  const secondDigit = day + month;
  return secondDigit * year;
};
function getSoulAge(dateOfBirth) {
  const digits = dateOfBirth.replace(/\//g, "").split("").map(Number);

  const getSum = (num) => {
    let sum = 0;
    while (num > 0 || sum > 9) {
      if (num === 0) {
        num = sum;
        sum = 0;
      }
      sum += num % 10;
      num = Math.floor(num / 10);
    }
    return sum;
  };

  let soulAge = getSum(digits.reduce((acc, curr) => acc + curr, 0));

  return soulAge;
}
function getCurrentAge(dateOfBirth) {
  const birthDate = new Date(dateOfBirth);
  const currentDate = new Date();
  const ageInMilliseconds = currentDate - birthDate;

  
  const millisecondsPerYear = 1000 * 60 * 60 * 24 * 365.25; 
  let currentAge = Math.ceil(ageInMilliseconds / millisecondsPerYear);
  if (currentAge < 0) {
    currentAge *= -1;
  }
  return currentAge;
}

